 importer::Plan effectivePlan(){auto &donor=selected();bool keep=keepColors_&&gtk_toggle_button_get_active(GTK_TOGGLE_BUTTON(keepColors_));auto plan=importer::defaultPlan(source_,donor.id,keep);auto names=importer::donorMaterialNames(stock_,donor.id);auto resolve=[&](const std::string &list){size_t start=0;while(start<=list.size()){auto end=list.find('|',start);auto candidate=list.substr(start,end==std::string::npos?std::string::npos:end-start);start=end==std::string::npos?list.size()+1:end+1;auto wanted=lower(candidate);for(auto &name:names){auto available=lower(name);if(available==wanted||available.rfind(wanted+"_",0)==0||available.rfind(wanted,0)==0)return candidate;}}return std::string();};for(auto &binding:plan.materials){if(binding.templateMaterial.find('|')!=std::string::npos){auto resolved=resolve(binding.templateMaterial);if(!resolved.empty())binding.templateMaterial=resolved;}auto it=materialOverrides_.find(binding.category);if(it==materialOverrides_.end())continue;binding.importTexture=it->second.importTexture;if(it->second.size)binding.size=it->second.size;binding.finish=it->second.finish;if(!it->second.templateName.empty()&&std::find(names.begin(),names.end(),it->second.templateName)!=names.end())binding.templateMaterial=it->second.templateName;}for(auto &binding:plan.materials)binding.size=importer::qualityTextureSize(binding.size,binding.category,quality());return plan;}
